import{z as n,x as s,o as e,c as d,q as l,j as i,D as B,d as A,s as o,S as t,b as a}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"保险的需求与道德风险","description":"","frontmatter":{"title":"保险的需求与道德风险","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/hi-demand-moralhazard.md","filePath":"econ/hi-demand-moralhazard.md","lastUpdated":1791413859000}'),p={name:"econ/hi-demand-moralhazard.md"};function D(m,E,h,c,C,u){const r=s("Mermaid");return e(),d("div",null,[E[2]||(E[2]=l('<h1 id="保险的需求与道德风险" tabindex="-1">保险的需求与道德风险 <a class="header-anchor" href="#保险的需求与道德风险" aria-label="Permalink to &quot;保险的需求与道德风险&quot;">​</a></h1><div class="epigraph"><p>保险的收益在风险的厌恶一侧，代价在行为的一侧：损失一旦被摊平，患者面对的治疗价格与事故的概率都变了。</p><footer>—— 据 Arrow, Uncertainty and the Welfare Economics of Medical Care, AER 1963；Pauly, The Economics of Moral Hazard, AER 1968 整理</footer></div><p><a href="/econ/bx-policy-map">上一课</a>把行为公共政策收束：判据先于工具，不对称家长制、自由家长制、有限修复三道门槛递增，判据与证据一个管该不该、一个管配多少。本课是「健康与保险经济学」的第一课，把保险本身当商品来分析：给定风险偏好与保费结构，买多少保障；以及买下保障之后，行为怎么变。后面的风险选择、健康劳动供给与药品定价，都默认你手里有这两件工具：保障的需求曲线，与道德风险的楔子。后课默认已经读完本课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/econ/risk-aversion">风险厌恶</a>课给出过基准：公平保费下充分投保，加载越高、自留越多。医疗保险不服从这张图，因为「损失」不是天降的火：医疗支出里有一部分是自己选的治疗量，事故概率里有一部分是自己选的预防努力。保险一旦把患者面对的价格从 \\(p\\) 压到自付 \\((1-c)p\\)，治疗量沿需求曲线上移；一旦把损失的财务后果摊平，预防的私人收益下降，事故概率上移。缺口因此是：这两条行为渠道并不需要「坏人」，只是价格变了——Pauly 把 Arrow 的福利命题收成这一句。分析必须同时写购买边际与行为边际，否则要么高估保险的福利收益，要么把道德风险误读成欺诈。</p><h3 id="两个边际" tabindex="-1">两个边际 <a class="header-anchor" href="#两个边际" aria-label="Permalink to &quot;两个边际&quot;">​</a></h3><p>事后边际：买了保险之后的用量。事前边际：投保之后更少的预防。文献里道德风险常只指前者；本课两个都记在账上，因为最优合同同时被两者推。</p><p><span class="marginnote">RAND 医疗保险实验把家庭随机分到从免费到 95% 共保的计划：免费组的医疗支出比高共保组高约三成，而平均健康结局的差异很小。使用边际的弹性是真的，其对平均人群的健康收益是小的——这两个数字是本课全部权衡的经验底座。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>合同写成一个三元组：保费 \\(\\pi\\)、共保率 \\(c\\)、免赔额 \\(D\\)。购买边际沿用期望效用：风险厌恶使愿付超过精算价，加载把自留风险推回来。行为边际是两条一阶条件：治疗量 \\(q\\) 选到边际收益等于自付价格 \\((1-c)p\\)，而社会的有效条件是边际收益等于边际成本 \\(p\\)，两者的差就是楔子；预防努力选到边际成本等于期望损失 \\(p(e)L\\) 的下降，投保把损失中自己承担的份额摊薄，这项收益随之变小。</p><p>免赔额的逻辑由此自明：小额风险的效用溢价是二阶的，加载却按比例收，把小风险保起来是用一阶成本买二阶收益。理性的合同因此把小额支出留给自付、把灾难性损失留给保险——这与观察到的免赔额结构一致。</p><p><span class="marginnote">术语翻译：免赔额（deductible）=起付线——一年内先自付满 X 元，超出部分才按比例报销。它故意让你在小账单上面对真实价格，把「用一阶成本保二阶收益」的亏本买卖挡在合同外。</span></p>',12)),(e(),i(t,null,{default:B(()=>[o(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20RA%5B%22%E9%A3%8E%E9%99%A9%E5%8E%8C%E6%81%B6%EF%BC%9A%E6%84%BF%E4%BB%98%E8%B6%85%E8%BF%87%E7%B2%BE%E7%AE%97%E4%BB%B7%22%5D%20--%3E%20BUY%5B%22%E8%B4%AD%E4%B9%B0%E5%90%88%E5%90%8C%EF%BC%9A%E4%BF%9D%E8%B4%B9%E3%80%81%E5%85%B1%E4%BF%9D%E3%80%81%E5%85%8D%E8%B5%94%22%5D%0A%20%20BUY%20--%3E%20USE%5B%22%E4%BA%8B%E5%90%8E%E8%BE%B9%E9%99%85%EF%BC%9A%E8%87%AA%E4%BB%98%E4%BB%B7%E6%A0%BC%E5%8E%8B%E4%BD%8E%EF%BC%8C%E7%94%A8%E9%87%8F%E4%B8%8A%E5%8D%87%22%5D%0A%20%20BUY%20--%3E%20PREV%5B%22%E4%BA%8B%E5%89%8D%E8%BE%B9%E9%99%85%EF%BC%9A%E9%A2%84%E9%98%B2%E6%94%B6%E7%9B%8A%E6%91%8A%E8%96%84%22%5D%0A%20%20USE%20--%3E%20WL%5B%22%E7%A6%8F%E5%88%A9%E6%8D%9F%E5%A4%B1%EF%BC%9A%E8%BE%B9%E9%99%85%E6%94%B6%E7%9B%8A%E4%BD%8E%E4%BA%8E%E6%88%90%E6%9C%AC%22%5D%0A%20%20PREV%20--%3E%20P%5B%22%E4%BA%8B%E6%95%85%E6%A6%82%E7%8E%87%E4%B8%8A%E5%8D%87%22%5D%0A%20%20WL%20--%3E%20OPT%5B%22%E6%9C%80%E4%BC%98%E5%85%B1%E4%BF%9D%E7%8E%87%EF%BC%9A%E5%B9%B3%E6%BB%91%E5%AF%B9%E6%BF%80%E5%8A%B1%22%5D%0A%20%20P%20--%3E%20OPT%0A"})]),fallback:B(()=>[...E[0]||(E[0]=[A(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[A("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,"把道德风险画成楔子之后，「最优保障多少」不再是规范口号，而是内部解：自付份额升高，风险平滑变差、楔子变小；自付份额降低，反之为。最优合同停在两种损失的边际相等处。免赔额把小风险的楔子整个拿掉，是同一逻辑在支出分布上的版本。",-1)),E[5]||(E[5]=a("p",null,[a("span",{class:"marginnote"},"数字实例：某药真实成本 100 元，对患者只值 30 元——社会角度不该用。若保险报销 90%，自付价 10 元，患者会买：个人账面赚 20 元，社会净亏 70 元。这道「个人理性、社会亏本」的缺口就是楔子的尺寸。")],-1)),(e(),i(t,null,{default:B(()=>[o(r,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20C%5B%22%E8%87%AA%E4%BB%98%E4%BB%BD%E9%A2%9D%20(1-c)%20%E4%BB%8E%200%20%E5%BE%80%E4%B8%8A%E8%B0%83%22%5D%20--%3E%20R%5B%22%E9%A3%8E%E9%99%A9%E5%B9%B3%E6%BB%91%E5%8F%98%E5%B7%AE%3A%20%E8%87%AA%E6%8B%85%E6%B3%A2%E5%8A%A8%E5%8F%98%E5%A4%A7%22%5D%0A%20%20C%20--%3E%20W%5B%22%E6%A5%94%E5%AD%90%E5%8F%98%E5%B0%8F%3A%20%E7%94%A8%E9%87%8F%E4%B8%8E%E4%BA%8B%E6%95%85%E6%8E%A5%E8%BF%91%E7%A4%BE%E4%BC%9A%E6%9C%80%E4%BC%98%22%5D%0A%20%20R%20--%3E%20EQ%5B%22%E6%9C%80%E4%BC%98%E5%90%88%E5%90%8C%E5%81%9C%E5%9C%A8%E4%B8%A4%E7%A7%8D%E6%8D%9F%E5%A4%B1%E7%9A%84%E8%BE%B9%E9%99%85%E7%9B%B8%E7%AD%89%E5%A4%84%22%5D%0A%20%20W%20--%3E%20EQ%0A%20%20EQ%20--%3E%20D%5B%22%E5%B0%8F%E9%A3%8E%E9%99%A9%3A%20%E7%94%A8%E5%85%8D%E8%B5%94%E9%A2%9D%E6%8A%8A%E6%A5%94%E5%AD%90%E6%95%B4%E4%B8%AA%E6%8B%BF%E6%8E%89%22%5D%0A%20%20EQ%20--%3E%20B%5B%22%E7%81%BE%E9%9A%BE%E9%A3%8E%E9%99%A9%3A%20%E7%95%99%E7%BB%99%E4%BF%9D%E9%99%A9%E5%B9%B3%E6%BB%91%22%5D%0A"})]),fallback:B(()=>[...E[1]||(E[1]=[A(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=l('<p>测量因此也有纪律：把保障的价格（自付份额）变化当工具，用量反应是道德风险，参保反应混着选择——那是下一课的对象。RAND 的贡献是第一次把两者分开：随机分派使选择不进估计，剩下的是干净的用量弹性。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写签约前的类型：健康风险高的人更想买慷慨保单，这是逆向选择，下一课用 Rothschild–Stiglitz 的机器处理。也不写动态合同与长期保单关系，不写支付方式把道德风险搬到供给侧的版本——按人头付费是同一楔子贴在医生身上。识别上注意：选择与激励混在一起，只有随机分派或价格工具的外生变化能拆开。</p><p><span class="marginnote">常见误区：以为治理道德风险只要提高保费。保费是入场费，动它改变的是「谁参保」（下一课的选择问题）；楔子在用量边际上，动自付份额与免赔额才动得了用量。</span></p><p>后课默认：合同由 \\((\\pi,c,D)\\) 描述；道德风险是价格楔子，不是道德败坏；测道德风险要动价格，不能只看谁买了什么。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>保险需求由风险厌恶与加载决定；医疗的特殊性在于损失部分可选、概率部分可选。</li><li>道德风险是事后用量与事前预防两条价格楔子，不是欺诈。</li><li>最优共保与免赔额是「保险价值对激励损失」的内部解；小风险不值得保。</li><li>RAND 实验给出干净的用量弹性：支出对自付份额敏感，平均健康结局不敏感。</li><li>出处：Arrow, <em>AER</em> 1963；Pauly, <em>AER</em> 1968；Manning 等 1987（RAND 医疗保险实验）；Einav–Finkelstein 对道德风险测量的整理。</li></ul>',7))])}const _=n(p,[["render",D]]);export{F as __pageData,_ as default};
